<?php $scanDisabled=scan_buttons_disabled(); ob_start(); ?><h1>Sites</h1><table><tr><th>Name</th><th>Path</th><th>Type</th><th>CMS</th><th>Last scan</th><th>Findings</th><th>Risk</th><th>Actions</th></tr><?php foreach($sites as $s): $risk=['','low','medium','high','critical'][(int)($s['risk_score']??0)]??'none'; ?><tr><td><?= e($s['name']) ?></td><td><code><?= e($s['path']) ?></code></td><td><?= e($s['type']) ?></td><td><?= e($s['cms_type']) ?></td><td><?= e($s['last_scan_at']) ?></td><td><?= e($s['findings_count']) ?></td><td><?= $risk==='none'?'none':'<span class="badge '.e($risk).'">'.e($risk).'</span>' ?></td><td><form class="scan-form" method="post" action="/scan/start"><input type="hidden" name="scope" value="site"><input type="hidden" name="value" value="<?= e($s['path']) ?>"><select class="input" name="profile"><?php foreach(['fast','standard','deep'] as $p): ?><option value="<?= $p ?>"><?= $p ?></option><?php endforeach ?></select><select class="input" name="max_seconds"><option value="300">5 min</option><option value="900">15 min</option><option value="1800">30 min</option><option value="0">Unlimited/manual</option></select><button class="btn small" <?= $scanDisabled ? 'disabled' : '' ?>>Scan this site</button></form></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
